using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Clients; [Authorize] public class DetailsModel:PageModel{private readonly OrcaFacilDbContext _db; private readonly ICurrentUserService _current; public Client? Client{get;private set;} public DetailsModel(OrcaFacilDbContext db,ICurrentUserService current){_db=db;_current=current;} public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){Client=await _db.Clients.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==_current.UserId&&!x.IsDeleted,ct); return Client is null?NotFound():Page();} public string MaskedDocument=>BrazilianDocument.Mask(Client?.DocumentType,Client?.DocumentNumber);}
